type Categoria = typeof CATEGORIAS[number];

// ============================================
// LER DADOS SALVOS
// ============================================

function lerDadosClube(entrada: string | null): DadosClube {
  if (!entrada) {
    return { ...DADOS_INICIAIS };
  }

  try {
    const antigo = JSON.parse(entrada);

    const validos = new Set<PremioId>(
      PREMIOS.map(p => p.id)
    );

    // Mantém a compatibilidade com prêmios antigos.
    validos.add('borboletas_jardim');

    const resgatados: PremioId[] =
      Array.isArray(antigo.resgatados)
        ? antigo.resgatados.filter(
            (id: unknown): id is PremioId =>
              typeof id === 'string' &&
              validos.has(id as PremioId)
          )
        : [];

    return {
      resgatados,
      tema:
        antigo.tema === 'menta' ||
        antigo.tema === 'aurora'
          ? antigo.tema
          : 'lavanda',
      titulo:
        typeof antigo.titulo === 'string'
          ? antigo.titulo
          : '',
      gratidao:
        typeof antigo.gratidao === 'string'
          ? antigo.gratidao
          : '',
      molduraAtiva:
        typeof antigo.molduraAtiva === 'string'
          ? antigo.molduraAtiva
          : 'nenhuma',
    };
  } catch {
    return { ...DADOS_INICIAIS };
  }
}

// ============================================
// FUNÇÕES AUXILIARES
// ============================================

function limitar(valor: number) {
  return Math.max(0, Math.min(100, valor));
}

function nivelPorPontos(pontos: number) {
  return Math.floor(pontos / 100) + 1;
}

function tituloDoNivel(nivel: number) {
  if (nivel >= 10) return 'Mestre do Autocuidado';
  if (nivel >= 7) return 'Especialista em Bem-Estar';
  if (nivel >= 5) return 'Guardião do Equilíbrio';
  if (nivel >= 3) return 'Explorador do Bem-Estar';
  return 'Iniciante do Autocuidado';
}

function emojiDoNivel(nivel: number) {
  if (nivel >= 10) return '👑';
  if (nivel >= 7) return '💎';
  if (nivel >= 5) return '🏆';
  if (nivel >= 3) return '🌟';
  return '🌱';
}

